// Schema Definition


export type BrowserTypingProps = Record<string, any>;

const BrowserTyping: React.FC<BrowserTypingProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 8,
  browserUrl = "google.com",
  slideInDuration = 1.2,
  typingSpeed = 3,
  browserScale = 1.0,
  xOffset = 0,
}) => {
  useFontLoader(["Inter", "Roboto"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Layout Calculations ---
  // Browser dimensions
  const browserWidth = width * 0.9; // 90% of screen width
  const browserHeight = height * 0.6; // Tall enough to look like a window
  const headerHeight = 60;
  const controlSize = 12;
  const addressBarHeight = 36;
  
  // Position vertically: Center the header around the 30% mark (visual focal point)
  const verticalOffset = height * 0.3 - headerHeight / 2;

  // --- Animation Logic ---

  // 1. Slide In Animation
  // Start off-screen right (width), end at centered (width - browserWidth) / 2 PLUS the requested xOffset
  
  const slideDurationFrames = slideInDuration * fps;
  
  const slideProgress = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 90, mass: 1 },
    durationInFrames: slideDurationFrames,
  });

  // X Position: Starts at width (just off screen right), ends at calculated center + user offset
  const startX = width;
  const endX = ((width - browserWidth) / 2) + xOffset;
  const translateX = interpolate(slideProgress, [0, 1], [startX, endX]);

  // 2. Typing Animation
  // Starts after slide finishes + small pause
  const typingStartFrame = slideDurationFrames + 15; // 0.5s pause (approx)
  
  // Calculate how many characters to show
  const charsToShow = Math.floor(
    interpolate(
      frame - typingStartFrame,
      [0, browserUrl.length * typingSpeed],
      [0, browserUrl.length],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    )
  );
  
  const visibleUrl = browserUrl.slice(0, charsToShow);
  const isTypingDone = charsToShow === browserUrl.length;

  // 3. Blinking Cursor
  // Only visible while typing or shortly after
  const cursorOpacity = Math.sin(frame / 5); 
  const showCursor = frame > typingStartFrame;

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Inter, sans-serif",
        justifyContent: "flex-start",
        alignItems: "flex-start",
        overflow: "hidden",
      }}
    >
      {/* Browser Window Container */}
      <div
        style={{
          position: "absolute",
          top: verticalOffset,
          left: 0, // Controlled by transform
          width: browserWidth,
          height: browserHeight,
          backgroundColor: "#ffffff",
          borderRadius: 12,
          boxShadow: "0 20px 50px rgba(0,0,0,0.15)",
          transform: `translateX(${translateX}px) scale(${browserScale})`,
          transformOrigin: "center top", // Scale from top center to keep vertical position
          display: "flex",
          flexDirection: "column",
          overflow: "hidden", // Clip content to rounded corners
        }}
      >
        {/* Browser Header / Toolbar */}
        <div
          style={{
            height: headerHeight,
            backgroundColor: "#f0f2f5", // Light gray like macOS/Chrome
            borderBottom: "1px solid #e0e0e0",
            display: "flex",
            alignItems: "center",
            padding: "0 20px",
            gap: 16,
            flexShrink: 0,
          }}
        >
          {/* Window Controls (Traffic Lights) */}
          <div style={{ display: "flex", gap: 8 }}>
            <div style={{ width: controlSize, height: controlSize, borderRadius: "50%", backgroundColor: "#ff5f56" }} />
            <div style={{ width: controlSize, height: controlSize, borderRadius: "50%", backgroundColor: "#ffbd2e" }} />
            <div style={{ width: controlSize, height: controlSize, borderRadius: "50%", backgroundColor: "#27c93f" }} />
          </div>

          {/* URL Bar */}
          <div
            style={{
              flex: 1,
              height: addressBarHeight,
              backgroundColor: "#ffffff",
              borderRadius: 6, // Slightly rounded
              display: "flex",
              alignItems: "center",
              padding: "0 12px",
              boxShadow: "0 1px 2px rgba(0,0,0,0.05)",
              border: "1px solid #e5e7eb", // Subtle border
              fontSize: 18, // Readable size
              color: "#374151",
              overflow: "hidden",
            }}
          >
            {/* Lock Icon */}
            <div style={{ marginRight: 8, display: "flex", alignItems: "center", opacity: 0.6 }}>
              <LockIcon size={16} />
            </div>

            {/* URL Text */}
            <div style={{ whiteSpace: "nowrap", display: "flex", alignItems: "center" }}>
              <span>{visibleUrl}</span>
              {showCursor && (
                <span
                  style={{
                    display: "inline-block",
                    width: 2,
                    height: 20,
                    backgroundColor: "#3b82f6", // Blue cursor
                    marginLeft: 2,
                    opacity: cursorOpacity > 0 ? 1 : 0,
                  }}
                />
              )}
            </div>
          </div>
        </div>

        {/* Browser Content (Skeleton UI) */}
        <div
          style={{
            flex: 1,
            backgroundColor: "#ffffff",
            padding: "40px",
            display: "flex",
            flexDirection: "column",
            gap: 30,
          }}
        >
            {/* Skeleton Block 1 (Hero) */}
            <div
              style={{
                width: "100%",
                height: 150,
                backgroundColor: "#e5e7eb", // Skeleton gray
                borderRadius: 8,
              }}
            />
            
            {/* Skeleton Lines */}
            <div style={{ display: "flex", flexDirection: "column", gap: 15 }}>
                <div style={{ width: "80%", height: 24, backgroundColor: "#f3f4f6", borderRadius: 4 }} />
                <div style={{ width: "90%", height: 24, backgroundColor: "#f3f4f6", borderRadius: 4 }} />
                <div style={{ width: "60%", height: 24, backgroundColor: "#f3f4f6", borderRadius: 4 }} />
            </div>

             {/* Skeleton Block 2 (Secondary) */}
             <div
              style={{
                marginTop: 20,
                width: "100%",
                height: 200,
                backgroundColor: "#f9fafb", // Lighter gray
                borderRadius: 8,
                border: "2px dashed #e5e7eb"
              }}
            />
        </div>
      </div>
    </AbsoluteFill>
  );
};

